import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def check_prime_power(X, a):
    # Check if X is an a-th power of an integer
    # Calculate the a-th root
    p_float = X**(1/a)
    p_candidate = round(p_float)

    # Check if p_candidate^a is exactly X
    if p_candidate**a != X:
        return None # Not a perfect a-th power

    # Check if p_candidate is prime
    if is_prime(p_candidate):
        return p_candidate
    else:
